const modal=document.getElementById('modal'),panel=document.getElementById('panel'),toast=document.getElementById('toast'),campaignApp=document.getElementById('campaignApp');let previousFocus=null,chosenRuler=null,game=null;
const rulers={
 harold:{name:'Harold II Godwinson',realm:'Kingdom of England',short:'England',mark:'H',difficulty:'High · exposed',seal:'House of Godwin',bio:'Crowned at Westminster on 6 January 1066, Harold inherited a kingdom facing rival claims and threats across the Channel and North Sea. The campaign opens on the day of his coronation.',why:'A compact realm with strong local resources, but three dynastic claimants and a narrow window to act.',start:{gold:78,levies:24,legitimacy:72},events:[['6 Jan 1066','A contested crown','Harold is crowned king after Edward the Confessor’s death. His authority will be tested by rival claims.'],['Spring 1066','Watch the coasts','William of Normandy prepares to press his claim; the northern threat is also gathering.'],['September 1066','The northern invasion','Historically, Harald Hardrada and Tostig landed in the north before Harold’s march to face them.']],sources:[['Royal Family: Harold II','https://www.royal.uk/harold-ii-r-jan-oct-1066'],['Encyclopaedia Britannica: Harold II','https://www.britannica.com/biography/Harold-II']]},
 philip:{name:'Philip I',realm:'Kingdom of France',short:'France',mark:'P',difficulty:'Moderate · young king',seal:'House of Capet',bio:'Philip became king in 1060 as a child. His mother, Anne of Kyiv, and Baldwin V of Flanders acted as regents during his minority; by 1066 the young Capetian king was beginning to rule in his own right.',why:'A royal title and a growing dynasty, balanced by youthful rule and the limited reach of royal authority.',start:{gold:68,levies:20,legitimacy:66},events:[['1060','A child king','Philip succeeds his father Henry I at about eight years old; a regency governs during his minority.'],['1066','Coming of age','At fourteen, Philip begins to exercise kingship amid the powerful principalities of France.'],['1066','Across the Channel','William of Normandy is both a powerful vassal and a claimant to the English crown.']],sources:[['Encyclopaedia Britannica: Philip I','https://www.britannica.com/biography/Philip-I-king-of-France']]},
 constantine:{name:'Constantine X Doukas',realm:'Byzantine Empire',short:'Byzantium',mark:'C',difficulty:'High · imperial strains',seal:'House of Doukas',bio:'Constantine X ruled the Byzantine Empire from 1059 until his death in 1067. His reign sat within a period of mounting military and political pressure on the empire’s eastern frontiers.',why:'An imperial treasury and prestige, but a vast frontier to defend and a fragile succession ahead.',start:{gold:92,levies:27,legitimacy:69},events:[['1059','A new emperor','Constantine X succeeds Isaac I Komnenos, beginning the Doukas dynasty’s rule.'],['1066','Frontier pressures','The empire must manage military demands across distant and varied frontiers.'],['1067','A succession ahead','Constantine’s death in 1067 will leave Empress Eudokia and their son Michael central to succession.']],sources:[['Encyclopaedia Britannica: Constantine X','https://www.britannica.com/biography/Constantine-X-Ducas'],['Dumbarton Oaks: Constantine X','https://www.doaks.org/resources/online-exhibits/gods-regents-on-earth-a-thousand-years-of-byzantine-imperial-seals/rulers-of-byzantium/constantine-x-doukas-1059-67']]},
 iziaslav:{name:'Iziaslav I Yaroslavich',realm:'Kievan Rus’ · Kyiv',short:'Kievan Rus’',mark:'I',difficulty:'Very high · princely rivalries',seal:'Rurikid prince',bio:'Iziaslav, eldest son of Yaroslav the Wise, held Kyiv from 1054. His rule depended on cooperation among the senior princes, a balance that would break in 1068 when a popular revolt drove him from the city.',why:'A powerful seat but no simple centralized state: dynastic cooperation and local politics are crucial.',start:{gold:64,levies:23,legitimacy:61},events:[['1054','The princes’ settlement','After Yaroslav the Wise’s death, Iziaslav becomes senior prince in Kyiv alongside his brothers.'],['1066','A fragile accord','The princes’ shared order remains vulnerable to military reverses and disputes over authority.'],['1068','Revolt in Kyiv','Historically, defeat by the Cumans was followed by an uprising that forced Iziaslav to flee Kyiv.']],sources:[['Encyclopedia of Ukraine: Iziaslav Yaroslavich','https://www.encyclopediaofukraine.com/display.asp?linkpath=pages%5CI%5CZ%5CIziaslavYaroslavych.htm']]},
 robert:{name:'Robert Guiscard',realm:'Norman Italy · Apulia and Calabria',short:'Norman Italy',mark:'R',difficulty:'Moderate · expansionist',seal:'House of Hauteville',bio:'A Norman adventurer who became duke of Apulia and Calabria in 1059, Robert built power in southern Italy and continued campaigns against Byzantine holdings. His authority rested on a coalition of Norman lords.',why:'An ambitious military base with room to expand, but competing lords and neighboring powers demand attention.',start:{gold:72,levies:26,legitimacy:59},events:[['1059','Duke by papal grant','The Treaty of Melfi recognizes Robert as duke of Apulia, Calabria and future Sicily.'],['1061','The Sicilian campaign','Robert and his brother Roger begin the Norman conquest of Sicily.'],['1066','A divided south','Norman power has grown, but southern Italy remains a patchwork of rival authorities.']],sources:[['Encyclopaedia Britannica: Robert Guiscard','https://www.britannica.com/biography/Robert-Guiscard']]}
};
const realmKeys={harold:'harold',philip:'philip',constantine:'constantine',iziaslav:'iziaslav',robert:'robert'};
function showToast(message){toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2500)}
function openModal(html){previousFocus=document.activeElement;panel.innerHTML=html;modal.classList.add('open');panel.querySelector('.close')?.focus()}
function closeModal(){modal.classList.remove('open');previousFocus?.focus?.()}
function header(kicker,title,sub){return `<header class="panel-header"><div><div class="panel-kicker">${kicker}</div><h2 id="panel-title">${title}</h2></div><button class="close" aria-label="Close">×</button></header>${sub?`<p class="panel-sub">${sub}</p>`:''}`}
function showEmpty(type){const title=type==='continue'?'No chronicle to resume':'No saved games',copy=type==='continue'?'Your story has not yet begun. Start the Norman Conquest to make your mark on history.':'There are no saved campaigns on this device yet.';openModal(`${header('The royal archive',title,'')}<div class="empty-state"><div class="empty-mark">♜</div><h3>The archive is empty</h3><p>${copy}</p></div><div class="panel-actions">${type==='continue'?'<button class="action" data-go="new">Begin the Norman Conquest</button>':''}<button class="action secondary" data-close>Return</button></div>`)}
function settingsScreen(){let music=localStorage.getItem('ch-music')!=='false',ambience=localStorage.getItem('ch-ambience')!=='false';openModal(`${header('Royal audience','Settings','Make the chronicle your own.')}<div class="setting"><div><div class="setting-name">Music</div><div class="setting-help">No score is bundled in this first playable build.</div></div><button class="toggle" role="switch" aria-label="Music" aria-checked="${music}" data-setting="music"></button></div><div class="setting"><div><div class="setting-name">Atmosphere</div><div class="setting-help">No ambient audio is bundled in this build.</div></div><button class="toggle" role="switch" aria-label="Atmosphere" aria-checked="${ambience}" data-setting="ambience"></button></div><div class="panel-actions"><button class="action" data-close>Done</button></div>`)}
function enterApp(screen='setup'){document.querySelector('.world').hidden=true;campaignApp.hidden=false;campaignApp.dataset.screen=screen;if(!document.getElementById('selectableTerritories').dataset.ready)prepareTerritories();renderScreen();}
function exitApp(){campaignApp.hidden=true;document.querySelector('.world').hidden=false;}
function prepareTerritories(){const normandy=document.querySelector('[data-polity="normandy"]');if(normandy){normandy.classList.remove('selectable');normandy.classList.add('ai-territory');normandy.setAttribute('aria-label','Duchy of Normandy · AI-controlled by William');normandy.setAttribute('tabindex','-1')}document.querySelectorAll('.territory.selectable').forEach(path=>{path.setAttribute('tabindex','0');path.setAttribute('role','button');path.setAttribute('aria-label',`${path.getAttribute('aria-label')} · playable realm`)});document.getElementById('selectableTerritories').dataset.ready='true';}
function rulerCards(){return Object.entries(rulers).map(([id,r])=>`<button class="ruler-card ${chosenRuler===id?'active':''}" data-ruler="${id}" aria-pressed="${chosenRuler===id}"><span class="seal" aria-label="Initial ${r.mark}, not a portrait">${r.mark}</span><span><span class="ruler-name">${r.name}</span><span class="ruler-realm">${r.realm}</span></span><span class="ruler-difficulty">${r.difficulty.split(' · ')[0]}</span></button>`).join('')}
function renderSetup(){const r=chosenRuler?rulers[chosenRuler]:null;document.getElementById('appDate').textContent='6 January 1066';document.getElementById('campaignSidebar').innerHTML=`<p class="sidebar-kicker">First playable campaign · 6 January 1066</p><h1 class="sidebar-title">The Norman<br>Conquest</h1><p class="sidebar-subtitle">Five rulers. One contested age.</p><p class="campaign-copy">Choose a ruler from the map or the roster. William of Normandy is represented as an AI power, not a playable ruler.</p><div class="ruler-list">${rulerCards()}</div>${r?`<section class="history-box"><p class="sidebar-kicker">${r.seal} · ${r.realm}</p><h2 class="history-title">${r.name}</h2><p class="history-text">${r.bio}</p><p class="history-text" style="margin-top:7px"><b>Difficulty:</b> ${r.why}</p><p class="provenance">Initial seal is a typographic marker, not a historical portrait. Sources: ${r.sources.map(([label,url])=>`<a href="${url}" target="_blank" rel="noopener">${label}</a>`).join(' · ')}</p></section>`:`<section class="history-box"><h2 class="history-title">A realm awaits</h2><p class="history-text">Select one of the five highlighted realms. The map can be dragged and zoomed; Normandy is shown as William’s AI-controlled duchy.</p><p class="provenance">The map is a real 1066 polity dataset rather than a modern political map. Its broad polities and borders are approximate and sometimes disputed.</p></section>`}<div class="app-actions"><button class="app-action secondary" data-app="back">Back to menu</button><button class="app-action" data-app="start" ${r?'':'disabled'}>Start campaign</button></div>`;updateMapSelection();}
function dateText(date){return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(`${date}T12:00:00Z`))}
function renderGame(){if(!game)return;const r=rulers[game.ruler],events=game.log.map(item=>`<article class="event"><div class="event-date">${item.date}</div><h3 class="event-title">${item.title}</h3><p class="event-copy">${item.copy}</p></article>`).join('');document.getElementById('appDate').textContent=dateText(game.date);document.getElementById('campaignSidebar').innerHTML=`<p class="sidebar-kicker">Your chronicle · ${r.realm}</p><h1 class="sidebar-title">${r.name}</h1><p class="sidebar-subtitle">Turn ${game.turn} · ${r.seal}</p><div class="stats-grid"><div class="stat"><div class="stat-label">Treasury</div><div class="stat-value">${game.gold}</div></div><div class="stat"><div class="stat-label">Levies</div><div class="stat-value">${game.levies}</div></div><div class="stat"><div class="stat-label">Legitimacy</div><div class="stat-value">${game.legitimacy}</div></div></div><p class="campaign-copy">A modest campaign foundation: advance time, manage three realm resources, and follow historically grounded chronicle markers. No battle or border changes are simulated yet.</p><div class="app-actions"><button class="app-action secondary" data-command="raise" ${game.gold<15?'disabled':''}>Raise levies · 15 gold</button><button class="app-action secondary" data-command="stores" ${game.gold<10?'disabled':''}>Provision · 10 gold</button></div><div class="app-actions" style="margin-top:4px"><button class="app-action" data-command="turn">End turn · one month</button></div><div class="history-box"><h2 class="history-title">Chronicle</h2><div class="event-list">${events}</div></div><p class="provenance">Ruler details and event context: ${r.sources.map(([label,url])=>`<a href="${url}" target="_blank" rel="noopener">${label}</a>`).join(' · ')}</p>`;updateMapSelection();}
function renderScreen(){if(campaignApp.dataset.screen==='game')renderGame();else renderSetup();}
function updateMapSelection(){document.querySelectorAll('.territory[data-polity]').forEach(p=>p.classList.toggle('is-selected',p.dataset.polity===chosenRuler));}
